Traditional RAG treats documents as independent entities in a flat vector space. Knowledge graph RAG adds explicit relationships between entities, enabling traversal-based retrieval.

```python
# Simple knowledge graph structure
class KnowledgeGraph:
    def __init__(self):
        self.entities = {}  # entity_id -> {name, type, description, embedding}
        self.relations = []  # (source_id, relation_type, target_id, properties)

    def add_entity(self, entity_id: str, name: str, entity_type: str, description: str):
        self.entities[entity_id] = {
            "name": name,
            "type": entity_type,
            "description": description,
            "embedding": embed(f"{name}: {description}")
        }

    def add_relation(self, source: str, relation: str, target: str, properties: dict = None):
        self.relations.append((source, relation, target, properties or {}))

    def get_neighbors(self, entity_id: str, relation_type: str = None, max_hops: int = 2):
        """Retrieve entities within max_hops of the given entity."""
        visited = set()
        frontier = {entity_id}
        results = []

        for hop in range(max_hops):
            next_frontier = set()
            for node in frontier:
                if node in visited:
                    continue
                visited.add(node)
                for source, rel, target, props in self.relations:
                    if source == node and (relation_type is None or rel == relation_type):
                        if target not in visited:
                            next_frontier.add(target)
                            results.append({
                                "entity": self.entities[target],
                                "relation": rel,
                                "from": self.entities[source]["name"],
                                "hop": hop + 1
                            })
                    elif target == node and (relation_type is None or rel == relation_type):
                        if source not in visited:
                            next_frontier.add(source)
                            results.append({
                                "entity": self.entities[source],
                                "relation": rel,
                                "from": self.entities[node]["name"],
                                "hop": hop + 1
                            })
            frontier = next_frontier

        return results
```

Beyond individual trace debugging, aggregate analysis reveals systematic issues:

```python
def systematic_analysis(traces: list[RAGTrace], eval_results: list[dict]) -> dict:
    """Identify systematic failure patterns across evaluation results."""

    # Group failures by category
    failure_categories = {
        "retrieval_failure": [],    # Low context recall
        "synthesis_failure": [],    # Low faithfulness despite good retrieval
        "relevance_failure": [],    # Answer doesn't address the question
        "no_answer_needed": [],     # System should have said "I don't know"
    }

    for trace, eval_result in zip(traces, eval_results):
        if eval_result["context_recall"] < 0.3:
            failure_categories["retrieval_failure"].append(trace)
        elif eval_result["context_recall"] > 0.7 and eval_result["faithfulness"] < 0.5:
            failure_categories["synthesis_failure"].append(trace)
        elif eval_result["answer_relevance"] < 0.5:
            failure_categories["relevance_failure"].append(trace)

    # Analyze each category
    report = {}
    for category, traces in failure_categories.items():
        if not traces:
            continue

        report[category] = {
            "count": len(traces),
            "percentage": len(traces) / len(eval_results) * 100,
            "example_queries": [t.query for t in traces[:5]],
            "common_patterns": analyze_common_patterns(traces)
        }

    return report
```

